    // ─────────── فصل ۳: ششم آوریل ۱۹۲۸ ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "April Sixth, 1928", titlePersian = "ششم آوریل ۱۹۲۸",
        paragraphs = listOf(
            StoryParagraph("Once a bitch always a bitch, what I say.", "سگ ماده‌ای که همیشه سگ ماده است، این چیزی است که می‌گویم."),
            StoryParagraph("I said that to myself as I walked to the store, and I meant it, and I meant it about my niece.", "این را به خودم گفتم همانطور که به مغازه می‌رفتم و منظورم بود و منظورم درباره خواهرزاده‌ام بود."),
            StoryParagraph("Miss Quentin, the daughter of my sister Caddy, was seventeen years old, and she was wild.", "میس کوئنتین، دختر خواهرم کدی، هفده ساله بود و وحشی بود."),
            StoryParagraph("She skipped school, she stayed out all night, she ran around with men.", "از مدرسه فرار می‌کرد، تمام شب بیرون می‌ماند، با مردان می‌گشت."),
            StoryParagraph("And she was my ward, and I had to support her, and I hated every moment of it.", "و او تحت سرپرستی من بود و باید تأمینش می‌کردم و از هر لحظه‌اش متنفر بودم."),
